import{_ as a,o as l,c as r,a2 as o}from"./chunks/framework.Crpw6aS5.js";const c=JSON.parse('{"title":"比亚迪","description":"","frontmatter":{"title":"比亚迪"},"headers":[],"relativePath":"03_companies/比亚迪.md","filePath":"03_companies/比亚迪.md"}'),i={name:"03_companies/比亚迪.md"};function e(h,t,d,n,s,g){return l(),r("div",null,[...t[0]||(t[0]=[o('<h1 id="比亚迪" tabindex="-1">比亚迪 <a class="header-anchor" href="#比亚迪" aria-label="Permalink to &quot;比亚迪&quot;">​</a></h1><h2 id="基本信息" tabindex="-1">基本信息 <a class="header-anchor" href="#基本信息" aria-label="Permalink to &quot;基本信息&quot;">​</a></h2><table tabindex="0"><thead><tr><th>项目</th><th>内容</th></tr></thead><tbody><tr><td>首次投资年份</td><td>2008年</td></tr><tr><td>持股数量</td><td>2.25亿股</td></tr><tr><td>初始投资成本</td><td>2.32亿美元（约18亿港元/2.3亿美元）</td></tr><tr><td>初始持股比例</td><td>9.9%-10%</td></tr><tr><td>投资主体</td><td><a href="/search.html?q=伯克希尔哈撒韦能源">伯克希尔哈撒韦能源</a>(BHE，伯克希尔持股89.8%-91.1%)</td></tr><tr><td>行业</td><td>新能源汽车、电池、电子产品制造</td></tr><tr><td>英文名</td><td>BYD Co. Ltd.</td></tr><tr><td>总部</td><td>中国深圳</td></tr><tr><td>创始人</td><td><a href="/search.html?q=王传福">王传福</a></td></tr><tr><td>成立年份</td><td>1995年</td></tr></tbody></table><h2 id="投资时间线" tabindex="-1">投资时间线 <a class="header-anchor" href="#投资时间线" aria-label="Permalink to &quot;投资时间线&quot;">​</a></h2><h3 id="_2008年-战略投资" tabindex="-1">2008年：战略投资 <a class="header-anchor" href="#_2008年-战略投资" aria-label="Permalink to &quot;2008年：战略投资&quot;">​</a></h3><ul><li><strong>9月</strong>：<a href="/search.html?q=伯克希尔哈撒韦能源">伯克希尔哈撒韦能源</a>（时称中美能源）以约<strong>2.32亿美元</strong>（约<strong>18亿港元</strong>）购入比亚迪2.25亿股，占公司总股本的<strong>9.9%</strong></li><li>投资背景：全球金融危机期间，比亚迪股价受到冲击，巴菲特看中其在新能源汽车和电池领域的领先地位</li><li>投资决策：巴菲特的老搭档<a href="/04_people/查理·芒格.html">查理·芒格</a>极力推荐，认为王传福是&quot;爱迪生与比尔·盖茨的结合体&quot;</li></ul><h3 id="_2009年-价值初显" tabindex="-1">2009年：价值初显 <a class="header-anchor" href="#_2009年-价值初显" aria-label="Permalink to &quot;2009年：价值初显&quot;">​</a></h3><ul><li><strong>年末持股</strong>：2.25亿股，持股比例9.9%</li><li><strong>投资成本</strong>：2.32亿美元</li><li><strong>市值</strong>：19.86亿美元</li><li><strong>回报倍数</strong>：约8.6倍</li></ul><h3 id="_2010年-年度股东会展车" tabindex="-1">2010年：年度股东会展车 <a class="header-anchor" href="#_2010年-年度股东会展车" aria-label="Permalink to &quot;2010年：年度股东会展车&quot;">​</a></h3><ul><li>巴菲特在2010年致股东信年会公告中特别提及：&quot;年度股东大会主题是飞机、火车和汽车，这让NetJets、<a href="/03_companies/BNSF铁路.html">BNSF铁路</a>和<a href="/03_companies/比亚迪.html">比亚迪</a>有机会展示&quot;</li><li>在年会上展示比亚迪电动车，体现了巴菲特对该投资的重视和信心</li></ul><h3 id="_2017年-长期持有" tabindex="-1">2017年：长期持有 <a class="header-anchor" href="#_2017年-长期持有" aria-label="Permalink to &quot;2017年：长期持有&quot;">​</a></h3><ul><li><strong>持股数量</strong>：2.25亿股（未变）</li><li><strong>持股比例</strong>：约8.2%（因比亚迪增发稀释）</li><li><strong>市值</strong>：19.61亿美元</li><li><strong>累计回报</strong>：约8.5倍</li></ul><h3 id="_2020年-进入十五大持仓" tabindex="-1">2020年：进入十五大持仓 <a class="header-anchor" href="#_2020年-进入十五大持仓" aria-label="Permalink to &quot;2020年：进入十五大持仓&quot;">​</a></h3><ul><li><strong>持股数量</strong>：2.25亿股</li><li><strong>持股比例</strong>：8.2%</li><li><strong>市值</strong>：58.97亿美元</li><li>成为伯克希尔&quot;十五大股权持仓&quot;之一</li><li><strong>回报倍数</strong>：约25倍</li></ul><h3 id="_2021年-持续增值" tabindex="-1">2021年：持续增值 <a class="header-anchor" href="#_2021年-持续增值" aria-label="Permalink to &quot;2021年：持续增值&quot;">​</a></h3><ul><li><strong>持股数量</strong>：2.25亿股</li><li><strong>持股比例</strong>：7.7%（进一步稀释）</li><li><strong>市值</strong>：76.93亿美元</li><li><strong>回报倍数</strong>：约33倍</li></ul><h3 id="_2022-2024年-减持退出" tabindex="-1">2022-2024年：减持退出 <a class="header-anchor" href="#_2022-2024年-减持退出" aria-label="Permalink to &quot;2022-2024年：减持退出&quot;">​</a></h3><ul><li><strong>2022年8月起</strong>：开始减持比亚迪股份</li><li>减持原因：投资回报已达到预期，资产配置调整</li><li>减持方式：通过港股市场逐步卖出</li></ul><h2 id="与巴菲特的关系" tabindex="-1">与巴菲特的关系 <a class="header-anchor" href="#与巴菲特的关系" aria-label="Permalink to &quot;与巴菲特的关系&quot;">​</a></h2><h3 id="投资逻辑" tabindex="-1">投资逻辑 <a class="header-anchor" href="#投资逻辑" aria-label="Permalink to &quot;投资逻辑&quot;">​</a></h3><p>巴菲特投资比亚迪的核心逻辑：</p><ol><li><strong>行业前景</strong>：看好新能源汽车和电池行业的长期发展</li><li><strong>管理层优秀</strong>：创始人<a href="/search.html?q=王传福">王传福</a>的技术创新能力与企业家精神</li><li><strong>成本优势</strong>：比亚迪在电池和电动车制造领域的成本控制能力</li><li><strong>中国机遇</strong>：投资于中国经济增长和产业升级的机会</li></ol><h3 id="巴菲特评价摘录" tabindex="-1">巴菲特评价摘录 <a class="header-anchor" href="#巴菲特评价摘录" aria-label="Permalink to &quot;巴菲特评价摘录&quot;">​</a></h3><p><strong>2008年年报</strong>：</p><blockquote><p>&quot;未来电动车我们会展示<a href="/03_companies/比亚迪.html">比亚迪</a>，我们拥有10%权益，中国这家公司真令人惊叹。&quot;</p></blockquote><p><strong>2010年年报</strong>：</p><blockquote><p>年度股东大会主题&quot;飞机、火车和汽车&quot;让<a href="/03_companies/比亚迪.html">比亚迪</a>有机会展示其电动车产品。</p></blockquote><h3 id="芒格的评价" tabindex="-1">芒格的评价 <a class="header-anchor" href="#芒格的评价" aria-label="Permalink to &quot;芒格的评价&quot;">​</a></h3><p><a href="/04_people/查理·芒格.html">查理·芒格</a>对比亚迪和<a href="/search.html?q=王传福">王传福</a>的评价极高：</p><ul><li>&quot;王传福是爱迪生与比尔·盖茨的结合体&quot;</li><li>&quot;比亚迪是我见过的最令人印象深刻的公司之一&quot;</li><li>多次在Daily Journal年会上赞扬比亚迪的创新能力</li></ul><h2 id="核心竞争优势" tabindex="-1">核心竞争优势 <a class="header-anchor" href="#核心竞争优势" aria-label="Permalink to &quot;核心竞争优势&quot;">​</a></h2><ol><li><strong>垂直整合能力</strong>：从电池到整车的一体化制造</li><li><strong>刀片电池技术</strong>：磷酸铁锂电池的安全性与能量密度突破</li><li><strong>成本控制</strong>：规模效应和产业链整合带来的成本优势</li><li><strong>中国市场地位</strong>：中国新能源汽车领军企业</li><li><strong>多元化业务</strong>：电动车、电池、电子产品代工多业务协同</li></ol><h2 id="财务表现" tabindex="-1">财务表现 <a class="header-anchor" href="#财务表现" aria-label="Permalink to &quot;财务表现&quot;">​</a></h2><table tabindex="0"><thead><tr><th>年份</th><th>持股数(亿股)</th><th>持股比例</th><th>成本(亿美元)</th><th>市值(亿美元)</th><th>回报倍数</th></tr></thead><tbody><tr><td>2008</td><td>2.25</td><td>9.9%-10%</td><td>2.32</td><td>2.32</td><td>1.0x</td></tr><tr><td>2009</td><td>2.25</td><td>9.9%</td><td>2.32</td><td>19.86</td><td>8.6x</td></tr><tr><td>2010</td><td>2.25</td><td>9.9%</td><td>2.32</td><td>11.82</td><td>5.1x</td></tr><tr><td>2017</td><td>2.25</td><td>8.2%</td><td>2.32</td><td>19.61</td><td>8.5x</td></tr><tr><td>2020</td><td>2.25</td><td>8.2%</td><td>2.32</td><td>58.97</td><td>25.4x</td></tr><tr><td>2021</td><td>2.25</td><td>7.7%</td><td>2.32</td><td>76.93</td><td>33.2x</td></tr></tbody></table><p><strong>注</strong>：</p><ul><li>持股比例变化主要源于比亚迪增发新股导致的稀释</li><li>2009年市值大幅上涨反映了市场对新能源汽车的预期</li><li>2020-2021年市值飙升受益于新能源汽车行业爆发</li></ul><h2 id="投资意义" tabindex="-1">投资意义 <a class="header-anchor" href="#投资意义" aria-label="Permalink to &quot;投资意义&quot;">​</a></h2><h3 id="战略价值" tabindex="-1">战略价值 <a class="header-anchor" href="#战略价值" aria-label="Permalink to &quot;战略价值&quot;">​</a></h3><ol><li><strong>新兴产业布局</strong>：巴菲特对新能源汽车领域的重要押注</li><li><strong>海外投资范例</strong>：伯克希尔少数的海外股票投资之一</li><li><strong>长期投资验证</strong>：验证了巴菲特价值投资理念在成长股中的适用性</li><li><strong>中国市场案例</strong>：展示了巴菲特对中国经济的信心</li></ol><h3 id="投资特点" tabindex="-1">投资特点 <a class="header-anchor" href="#投资特点" aria-label="Permalink to &quot;投资特点&quot;">​</a></h3><ul><li><strong>逆向投资</strong>：在2008年金融危机期间买入</li><li><strong>长期持有</strong>：持有14年（2008-2022），体现了耐心投资的回报</li><li><strong>超额收益</strong>：投资回报超过30倍，是巴菲特投资生涯中最成功的投资之一</li></ul><h2 id="相关人物" tabindex="-1">相关人物 <a class="header-anchor" href="#相关人物" aria-label="Permalink to &quot;相关人物&quot;">​</a></h2><ul><li><strong><a href="/search.html?q=王传福">王传福</a></strong>：比亚迪创始人、董事长兼总裁，被誉为&quot;中国新能源汽车教父&quot;</li><li><strong><a href="/04_people/查理·芒格.html">查理·芒格</a></strong>：伯克希尔副董事长，极力推动投资比亚迪的关键人物</li><li><strong><a href="/04_people/沃伦·巴菲特.html">沃伦·巴菲特</a></strong>：伯克希尔董事长，最终拍板投资决策</li><li><strong>李录</strong>：喜马拉雅资本创始人，最早向芒格推荐比亚迪的投资人</li></ul><h2 id="在股东信中的年份" tabindex="-1">在股东信中的年份 <a class="header-anchor" href="#在股东信中的年份" aria-label="Permalink to &quot;在股东信中的年份&quot;">​</a></h2><ul><li><strong>2008年</strong>：首次投资，在年会公告中提及</li><li><strong>2009年</strong>：出现在投资组合表格中</li><li><strong>2010年</strong>：年会展车，投资组合表格</li><li><strong>2017年</strong>：投资组合表格</li><li><strong>2020年</strong>：投资组合表格，成为十五大持仓</li><li><strong>2021年</strong>：投资组合表格</li></ul><h2 id="相关链接" tabindex="-1">相关链接 <a class="header-anchor" href="#相关链接" aria-label="Permalink to &quot;相关链接&quot;">​</a></h2><ul><li><a href="/search.html?q=2008年股东信">2008年股东信</a></li><li><a href="/search.html?q=2009年股东信">2009年股东信</a></li><li><a href="/search.html?q=2010年股东信">2010年股东信</a></li><li><a href="/search.html?q=2017年股东信">2017年股东信</a></li><li><a href="/search.html?q=2020年股东信">2020年股东信</a></li><li><a href="/search.html?q=2021年股东信">2021年股东信</a></li><li><a href="/search.html?q=王传福">王传福</a></li><li><a href="/04_people/查理·芒格.html">查理·芒格</a></li><li><a href="/search.html?q=伯克希尔哈撒韦能源">伯克希尔哈撒韦能源</a></li></ul><h2 id="关键原文出处" tabindex="-1">关键原文出处 <a class="header-anchor" href="#关键原文出处" aria-label="Permalink to &quot;关键原文出处&quot;">​</a></h2><p>以下为该公司在致股东信中被提及的关键年份，点击即可阅读完整翻译：</p><ul><li><a href="/03_companies/比亚迪.html">2008年：完整翻译|/01_letters/2008年/翻译</a></li><li><a href="/03_companies/比亚迪.html">2009年：完整翻译|/01_letters/2009年/翻译</a></li><li><a href="/03_companies/比亚迪.html">2010年：完整翻译|/01_letters/2010年/翻译</a></li><li><a href="/03_companies/比亚迪.html">2021年：完整翻译|/01_letters/2021年/翻译</a></li></ul><hr><p><strong>最后更新</strong>：2025年 <strong>数据来源</strong>：伯克希尔哈撒韦2008-2025年致股东信</p>',52)])])}const q=a(i,[["render",e]]);export{c as __pageData,q as default};
